package switchcase_practice_Basics;

public class Months {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		
	  
		switch(12) {
		 
		case 1:
			System.out.println("jaunary");
			break;
			
		case 2:
			System.out.println("febrauary");
			break;
			
		case 3:
			System.out.println("Marchi");
			break;
			
		case 4:
			System.out.println("April");
			break;
			
		case 5:
			System.out.println("May");
			break;
			
		case 6:
			System.out.println("June");
			break;
			
		case 7:
			System.out.println("juley");
			break;
			
		case 8:
			System.out.println("Agusta");
			break;
			
		case 9:
			 System.out.println("Septambar");
			break;
			
		case 10:
		System.out.println("Actobar");
		     break;
		case 11:
		System.out.println("Novembar");
		     break;
		case 12:
			System.out.println("Decembar");
			
			default:
				System.out.println("Invalid month");
				break;
		}
		}
	}
